// Check if we have all required info for booking
const input = $input.item.json;
const entities = input.entities || [];

// Required fields for booking
const requiredFields = {
  name: null,
  email: null,
  phone: null,
  date: null,
  time: null,
  service: null
};

// Extract entities
for (const entity of entities) {
  if (entity.type === 'name' || entity.label === 'name') {
    requiredFields.name = entity.value;
  }
  if (entity.type === 'email' || entity.label === 'email') {
    requiredFields.email = entity.value;
  }
  if (entity.type === 'phone' || entity.label === 'phone') {
    requiredFields.phone = entity.value;
  }
  if (entity.type === 'date' || entity.label === 'date') {
    requiredFields.date = entity.value;
  }
  if (entity.type === 'time' || entity.label === 'time') {
    requiredFields.time = entity.value;
  }
  if (entity.type === 'service' || entity.label === 'service') {
    requiredFields.service = entity.value;
  }
}

// Try to get name from sender if not in entities
if (!requiredFields.name && input.sender_name && input.sender_name !== 'Unknown') {
  requiredFields.name = input.sender_name;
}

// Check completeness
const missingFields = Object.entries(requiredFields)
  .filter(([key, value]) => !value)
  .map(([key]) => key);

const isComplete = missingFields.length === 0;
const hasMinimumInfo = requiredFields.name && (requiredFields.email || requiredFields.phone);

return {
  json: {
    ...input,
    booking_info: requiredFields,
    missing_fields: missingFields,
    is_complete: isComplete,
    has_minimum_info: hasMinimumInfo
  }
};

// Generate booking link for the website with prefilled info
const input = $input.item.json;
const bookingInfo = input.booking_info;

const baseUrl = 'https://louna-co.com';
const params = new URLSearchParams();

if (bookingInfo.name) {
  const nameParts = bookingInfo.name.split(' ');
  params.append('prenom', nameParts[0]);
  if (nameParts.length > 1) {
    params.append('nom', nameParts.slice(1).join(' '));
  }
}
if (bookingInfo.email) params.append('email', bookingInfo.email);
if (bookingInfo.phone) params.append('telephone', bookingInfo.phone);
if (bookingInfo.date) params.append('date', bookingInfo.date);
if (bookingInfo.time) params.append('heure', bookingInfo.time);

const bookingLink = params.toString() ? `${baseUrl}?${params.toString()}` : baseUrl;

return {
  json: {
    ...input,
    booking_link: bookingLink
  }
};

// Generate booking link for partial info
const input = $input.item.json;
const bookingInfo = input.booking_info;

// Build website booking link with prefilled info
const baseUrl = 'https://louna-co.com';
const params = new URLSearchParams();

if (bookingInfo.name) {
  const nameParts = bookingInfo.name.split(' ');
  params.append('prenom', nameParts[0]);
  if (nameParts.length > 1) {
    params.append('nom', nameParts.slice(1).join(' '));
  }
}
if (bookingInfo.email) {
  params.append('email', bookingInfo.email);
}
if (bookingInfo.phone) {
  params.append('telephone', bookingInfo.phone);
}

const bookingLink = params.toString() ? `${baseUrl}?${params.toString()}` : baseUrl;

// Generate message asking for missing info
const missingFieldsMessages = {
  'date': 'la date souhaitee',
  'time': "l'heure preferee",
  'service': 'le type de service',
  'email': 'votre adresse email',
  'phone': 'votre numero de telephone'
};

const missingList = input.missing_fields
  .filter(f => missingFieldsMessages[f])
  .map(f => missingFieldsMessages[f]);

let responseText = '';
if (missingList.length > 0) {
  responseText = `Pour finaliser votre reservation, j'aurais besoin de ${missingList.join(', ')}. Vous pouvez aussi reserver directement sur notre site : ${bookingLink}`;
} else {
  responseText = `Voici le lien pour finaliser votre reservation sur notre site : ${bookingLink}`;
}

return {
  json: {
    ...input,
    booking_link: bookingLink,
    reply_text: responseText,
    action: 'send_link',
    booking_status: 'link_sent'
  }
};

// Generate message for missing info
const input = $input.item.json;

const responseText = `Pour reserver un rendez-vous, j'aurais besoin de quelques informations: votre nom, email ou telephone, ainsi que vos preferences de date et heure. Pouvez-vous me les communiquer ?`;

return {
  json: {
    ...input,
    reply_text: responseText,
    action: 'request_info',
    booking_status: 'awaiting_info'
  }
};

// Send website booking link with complete info
const input = $input.item.json;
const bookingLink = input.booking_link || 'https://louna-co.com';

const responseText = `Super ! Voici le lien pour finaliser votre rendez-vous sur notre site : ${bookingLink} — Il ne vous reste plus qu'a confirmer vos disponibilites. A bientot !`;

return {
  json: {
    ...input,
    booking_id: null,
    booking_datetime: `${input.booking_info.date || ''} ${input.booking_info.time || ''}`.trim() || null,
    reply_text: responseText,
    action: 'send_link',
    booking_status: 'link_sent'
  }
};
